def esc(x): return html.escape(x, quote=True)
def art(r): return "an" if r[0].lower() in "aeiou" or r.startswith(("HR", "IT")) else "a"
def ul(xs): return "<ul>" + "".join(f"<li>{esc(x)}</li>" for x in xs) + "</ul>"
