URLS = []
def page(fname, clean, title, desc, body, schema=""):
    url = BASE + clean; URLS.append(url)
    os.makedirs(os.path.dirname(fname) or ".", exist_ok=True)
    ld = f'<script type="application/ld+json">{json.dumps(schema).replace("</", "<\\/")}</script>' if schema else ""
    open(fname, "w", encoding="utf-8").write(f'<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><style>{CSS}</style>{ld}</head><body><nav><a href="/">Free AI CV Tailor</a><a href="/guides/">Guides</a><a href="/#ats">ATS checker</a></nav>{body}{FOOT}</body></html>')

